const webhookData = $('Webhook — Nouvelle candidature').item.json;
const raw = webhookData.body || webhookData;
const candidateId = raw.candidateId;
const firstName   = raw.firstName || 'Candidat';
const lastName    = raw.lastName  || '';
const email       = raw.email;
const jobTitle    = raw.jobOfferTitle || 'le poste';

let cohereResult = null;
try { cohereResult = $input.first().json; } catch (e) { cohereResult = null; }

const hasValidScore = cohereResult && typeof cohereResult.aiScore === 'number';
const num = (v) => (typeof v === 'number' ? v : null);

const score              = hasValidScore ? cohereResult.aiScore : null;
const technicalScore     = hasValidScore ? num(cohereResult.aiScoreTechnical) : null;
const communicationScore = hasValidScore ? num(cohereResult.aiScoreCommunication) : null;
const seniorityScore     = hasValidScore ? num(cohereResult.aiScoreSeniorityMatch) : null;
const aiScoreSource      = hasValidScore ? cohereResult.aiScoreSource : 'UNAVAILABLE';
const candidateStatus    = hasValidScore ? cohereResult.status : null;

const mention = !hasValidScore ? 'Analyse en cours'
              : score >= 85 ? 'Excellent profil'
              : score >= 70 ? 'Bon profil'
              : score >= 60 ? 'Profil moyen'
              : 'Profil insuffisant';

const card = (inner) =>
  `    <div style="background: white; border: 2px solid #e2e8f0; border-radius: 8px; padding: 16px; margin: 16px 0;">\n` +
  `      <h3 style="color: #374151; margin-top:0;">\u{1F4CA} Analyse IA de votre profil</h3>\n${inner}    </div>`;

const scoreBlock = hasValidScore
  ? card(
      `      <div style="display: flex; align-items: center; gap: 12px;">\n` +
      `        <div style="background: #1e40af; color: white; font-size: 24px; font-weight: bold; padding: 12px 20px; border-radius: 8px;">${score}/100</div>\n` +
      `        <div>\n          <strong style="color: #1e40af;">${mention}</strong><br>\n` +
      `          <small style="color: #6b7280;">Score calculé par notre IA de recrutement</small>\n        </div>\n      </div>\n`)
  : card(
      `      <p style="color: #6b7280; margin:0;">Votre profil est en cours d'analyse par notre équipe RH. ` +
      `Vous serez tenu(e) informé(e) de l'avancement de votre candidature par e-mail.</p>\n`);

return [{
  json: {
    candidateId, firstName, lastName, email, jobTitle,
    score, mention, technicalScore, communicationScore, seniorityScore,
    aiScoreSource, status: candidateStatus, scoreBlock,
    processedAt: new Date().toISOString(),
    responsePayload: {
      status: hasValidScore ? 'ok' : 'score_unavailable',
      score, mention, candidateId,
      technicalScore, communicationScore, aiScoreSource,
      message: hasValidScore ? 'Candidature analysee par IA (Cohere)'
                             : 'Analyse IA indisponible, score non publie'
    }
  }
}];
